import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        R = int(next(iterator))
        C = int(next(iterator))
        K = int(next(iterator))

        count = 0
        for r in range(1, 9):
            for c in range(1, 9):
                dist_r = abs(r - R)
                dist_c = abs(c - C)
                if max(dist_r, dist_c) <= K:
                    count += 1

        results.append(str(count))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
